        ['app' => 'daftar', 'version' => '2.2.20', 'role_id' => null, 'title' => 'Daftar 2.2.20 – /alumni tetap di NIK + Reset NIK', 'changelog' => "/alumni tidak lagi auto-redirect ke biodata saat buka/reload link.\nBiodata: tombol Reset NIK di samping field NIK — hapus sesi dan kembali ke halaman input NIK.", 'released_at' => '2026-07-24 10:30:00'],
