        ['app' => 'api', 'version' => '2.13.35', 'role_id' => null, 'title' => 'API 2.13.35 – Anti-spam alert WA & lazy DB middleware', 'changelog' => "Alert fatal/5xx ke WA: path tanpa query string; kegagalan DB digabung satu signature + cooldown ~15 menit; maks 8 alert/jam (env ERROR_ALERT_*).\nRateLimitMiddleware / AuthMiddleware / OptionalAuthMiddleware: koneksi DB lazy (bukan di construct) agar gagal DB tidak fatal di bootstrap tiap webhook (mis. /api/wa/message-status).\nRate limit fail-open jika DB down; Auth mengembalikan 503.", 'released_at' => '2026-07-28 13:00:00'],
