        ['app' => 'api', 'version' => '2.13.43', 'role_id' => null, 'title' => 'API 2.13.43 – Notif WA rencana non-blocking', 'changelog' => "DeferredHttpTask: litespeed_finish_request (Hostinger) agar klien tidak menunggu kirim WA.\nNotif rencana pending/edit: template + queue dari backend saat create/update (body recipients).\nLink preview WA dimatikan untuk pesan ber-URL / kategori pengeluaran (cegah «Menunggu pesan ini» di beberapa HP).\nJeda ~0,45s antar penerima WA.", 'released_at' => '2026-08-02 22:00:00'],
        ['app' => 'ebeddien', 'version' => '7.1.77', 'role_id' => null, 'title' => 'eBeddien 7.1.77 – Simpan rencana tanpa tunggu WA', 'changelog' => "Simpan/ajukan rencana: penerima WA ikut di payload; pengiriman di backend setelah response.\nUI tidak lagi menunggu notifikasi WA selesai.\nBACKEND_VERSION 2.13.43.", 'released_at' => '2026-08-02 22:00:00'],
        ['app' => 'api', 'version' => '2.13.44', 'role_id' => null, 'title' => 'API 2.13.44 – Harden daftar WA + iPaymu staff send-wa', 'changelog' => "Login daftar: verifikasi WA wajib sender_wa = no_wa claimed; POST /auth/login-nik dinonaktifkan.\nNotif rencana: nomor WA penerima hanya dari DB pengurus (abaikan whatsapp body klien).\ncreateTransaction: defer_wa / X-Client-App ebeddien tidak auto-kirim WA.\nPOST /payment-transaction/{id}/send-wa: staff kirim QRIS (gambar) atau logo metode + caption ke nomor eksplisit.", 'released_at' => '2026-08-02 22:30:00'],
        ['app' => 'ebeddien', 'version' => '7.1.78', 'role_id' => null, 'title' => 'eBeddien 7.1.78 – Checkout iPayMu staff + Kirim WA', 'changelog' => "Pembayaran PSB / UWABA / tunggakan / khusus: pilih metode iPayMu (QRIS, VA, CStore, e-wallet), buat tagihan tanpa auto-WA, panel edit HP/email, tombol Kirim WA (QR atau logo metode).\nBACKEND_VERSION 2.13.44.", 'released_at' => '2026-08-02 22:30:00'],
        ['app' => 'ebeddien', 'version' => '7.1.79', 'role_id' => null, 'title' => 'eBeddien 7.1.79 – Panduan pas foto 3×4', 'changelog' => "Cetak Kartu (kamera & crop upload): kotak panduan 3×4 diperbesar hampir selebar layar.\nSiluet kepala & bahu agar posisi wajah selalu lurus — sama di kamera langsung dan saat geser/zoom foto upload.", 'released_at' => '2026-08-02 22:45:00'],
        ['app' => 'api', 'version' => '2.13.45', 'role_id' => null, 'title' => 'API 2.13.45 – myBeddien auth via WA (wa.me)', 'changelog' => "Daftar / lupa password / lupa username myBeddien: pola sama app daftar — prepare token + wa.me, user kirim sendiri, bot verifikasi sender_wa = no_wa, lalu balas link setup/reset atau username.\nTabel mybeddian_auth_wa_tokens. Password baru minimal 8 karakter.\nMYBEDDIEN_AUTH_WA_QR_NUMBER (default nomor QR daftar).", 'released_at' => '2026-08-02 23:00:00'],
        ['app' => 'mybeddien', 'version' => '1.2.86', 'role_id' => null, 'title' => 'myBeddien 1.2.86 – Daftar/lupa via WhatsApp', 'changelog' => "Daftar, lupa password, lupa username: setelah verifikasi data → Buka WhatsApp (pesan + token), balasan bot berisi link username/password atau username.\nSetup & ubah password: minimal 8 karakter, konfirmasi password, tidak bisa tempel.\nBACKEND_VERSION 2.13.45.", 'released_at' => '2026-08-02 23:00:00'],
        ['app' => 'api', 'version' => '2.13.46', 'role_id' => null, 'title' => 'API 2.13.46 – Fix balasan auth WA opt-out + LID', 'changelog' => "Balasan handshake myBeddien/daftar_santri_wa/ebeddien_daftar_wa tidak lagi diblok siap_terima_notif=0 (penyebab nomor tertentu tidak dapat balasan).\nVerifikasi pengirim mendukung mapping LID↔MSISDN di whatsapp___kontak.", 'released_at' => '2026-08-02 23:15:00'],
        ['app' => 'mybeddien', 'version' => '1.2.87', 'role_id' => null, 'title' => 'myBeddien 1.2.87 – Pilih WA + salin teks', 'changelog' => "Panel verifikasi WA: tombol WhatsApp biasa / WA Business (Android), Salin teks pesan, dan link wa.me default.\nBACKEND_VERSION 2.13.46.", 'released_at' => '2026-08-02 23:15:00'],
        ['app' => 'mybeddien', 'version' => '1.2.88', 'role_id' => null, 'title' => 'myBeddien 1.2.88 – Install PWA di login & header', 'changelog' => "Tombol Install aplikasi di halaman login (kartu sekunder di bawah form) serta ikon di kontrol auth (desktop/mobile).\nHeader: label Install selalu terlihat jika belum terpasang.\nManifest PWA dipasang sejak app siap agar prompt install tersedia sebelum login.", 'released_at' => '2026-08-03 06:00:00'],
        ['app' => 'ebeddien', 'version' => '7.1.80', 'role_id' => null, 'title' => 'eBeddien 7.1.80 – Install PWA di login & header', 'changelog' => "Tombol Install aplikasi di halaman login (kartu sekunder) serta ikon di kontrol auth.\nHeader: label Install selalu terlihat jika belum terpasang.\nService worker + manifest staff dipasang sejak app siap (bukan hanya setelah login/Beranda) agar install tersedia di auth.", 'released_at' => '2026-08-03 06:00:00'],
        ['app' => 'ebeddien', 'version' => '7.1.81', 'role_id' => null, 'title' => 'eBeddien 7.1.81 – Ubah massal UWABA terpadu', 'changelog' => "Manage Data UWABA → Ubah Massal: status+kategori satu kesatuan; diniyah/formal/LTTQ memakai cascade lembaga/tingkatan → kelas → kel (seperti edit satu santri), bukan kolom terpisah.", 'released_at' => '2026-08-03 06:15:00'],
        ['app' => 'ebeddien', 'version' => '7.1.82', 'role_id' => null, 'title' => 'eBeddien 7.1.82 – Detail santri dari nama Manage UWABA', 'changelog' => "Manage Data UWABA: klik NIS tetap ke halaman UWABA; klik nama membuka Detail Santri (global offcanvas, sama seperti Cari Santri → titik tiga).", 'released_at' => '2026-08-03 06:20:00'],
        ['app' => 'ebeddien', 'version' => '7.1.83', 'role_id' => null, 'title' => 'eBeddien 7.1.83 – Grup fitur Umum', 'changelog' => "Pengaturan → Fitur: grup Umum untuk kemampuan UI global (Cari Santri, Detail/Edit Santri, Detail User, Template WA).\nParent menu.umum tidak tampil di sidebar; akses diatur per aksi di satu tempat.", 'released_at' => '2026-08-03 06:30:00'],
        ['app' => 'api', 'version' => '2.13.47', 'role_id' => null, 'title' => 'API 2.13.47 – Format ack WA permintaan', 'changelog' => "Pesan 1 balasan daftar / lupa password / lupa username (myBeddien + app daftar): «Terima kasih. permintaan sedang diproses 🔄» lalu baris quote simpan nomor resmi pesantren.", 'released_at' => '2026-08-03 09:50:00'],
        ['app' => 'api', 'version' => '2.13.48', 'role_id' => null, 'title' => 'API 2.13.48 – WA pengajuan NIS format baru', 'changelog' => "Setelah upload KK: pesan 1 Waalaikumsalam + ack proses; pesan 2 detail review tanpa Assalamualaikum, ada catatan proses (hari/tanggal/jam WIB).\nKirim NIS & tolak: tanpa salam Assalamualaikum; langsung pemberitahuan + catatan proses waktu.", 'released_at' => '2026-08-03 09:55:00'],
