        ['app' => 'ebeddien', 'version' => '7.1.84', 'role_id' => null, 'title' => 'eBeddien 7.1.84 – Status Menunggu WA pengajuan NIS', 'changelog' => "Pengajuan NIS: filter/badge status Menunggu WA (KK sudah diunggah, menunggu konfirmasi token WhatsApp pemohon).", 'released_at' => '2026-08-03 10:30:00'],
