        ['app' => 'mybeddien', 'version' => '1.2.90', 'role_id' => null, 'title' => 'myBeddien 1.2.90 – Menu Saldo mode toko', 'changelog' => "Mode toko: menu Saldo (wallet cashless toko) — lihat saldo, riwayat, top-up.\nBACKEND_VERSION 2.13.50.", 'released_at' => '2026-08-03 10:45:00'],
        ['app' => 'api', 'version' => '2.13.51', 'role_id' => null, 'title' => 'API 2.13.51 – WA mismatch + ack bulanan', 'changelog' => "Pengirim WA ≠ nomor di aplikasi: balasan singkat + wa tercatat / wa pengirim.\nAck «Terima kasih. permintaan sedang diproses» max 1× per nomor per bulan kalender (tabel wa_permintaan_proses_ack).\nPesan KK diterima pengajuan NIS tetap ringkas (tanpa catatan proses / konfirmasi).", 'released_at' => '2026-08-03 20:50:00'],
