        ['app' => 'mybeddien', 'version' => '1.2.91', 'role_id' => null, 'title' => 'myBeddien 1.2.91 – Link setup/reset 10 menit', 'changelog' => "Pesan error setup akun & ubah password: masa aktif link 10 menit (selaras backend).\nBACKEND_VERSION 2.13.52.", 'released_at' => '2026-08-03 21:00:00'],
