        ['app' => 'ebeddien', 'version' => '7.1.85', 'role_id' => null, 'title' => 'eBeddien 7.1.85 – Count & checklist pengurus di Fitur', 'changelog' => "Pengaturan → Fitur → offcanvas role: tampil jumlah pengurus per role.\nKlik angka membuka offcanvas checklist pengurus (punya role di atas, belum di bawah; centang langsung assign/cabut).\nBACKEND_VERSION 2.13.53.", 'released_at' => '2026-08-05 10:45:00'],
