        ['app' => 'ebeddien', 'version' => '7.1.86', 'role_id' => null, 'title' => 'eBeddien 7.1.86 – Fix offcanvas checklist pengurus', 'changelog' => "Pengaturan → Fitur: offcanvas pengurus (klik count role) tidak langsung tertutup lagi.\nTombol count menampilkan ikon user + angka.", 'released_at' => '2026-08-05 11:15:00'],
        ['app' => 'api', 'version' => '2.13.55', 'role_id' => null, 'title' => 'API 2.13.55 – Harden profil & list pendaftar PII', 'changelog' => "GET /api/user/{id}: hapus bypass admin_ugt tanpa fitur; rekening hanya self/super_admin.\nget-all-pendaftar: NIK/No.KK disamarkan di list; include_pii=1 hanya super_admin/admin_psb/petugas_psb/panitia_tes (+ audit).\nSembunyikan X-Powered-By (index.php, SecurityHeaders, .htaccess).", 'released_at' => '2026-08-05 11:35:00'],
        ['app' => 'ebeddien', 'version' => '7.1.87', 'role_id' => null, 'title' => 'eBeddien 7.1.87 – Export pendaftar dengan PII terkontrol', 'changelog' => "Export Excel Data Pendaftar meminta include_pii agar NIK/KK penuh hanya saat ekspor (bukan di cache list).\nBACKEND_VERSION 2.13.55.", 'released_at' => '2026-08-05 11:35:00'],
        ['app' => 'api', 'version' => '2.13.56', 'role_id' => null, 'title' => 'API 2.13.56 – Fix history PSB + anti double payment', 'changelog' => "GET /pendaftaran/history: baca psb___transaksi (bukan tabel legacy) — perbaiki 500.\ncreate-payment-psb: tolak jika sudah lunas / melebihi kurang / duplikat ≤45 dtk (409), kecuali confirm_overpay / confirm_duplicate.", 'released_at' => '2026-08-05 12:00:00'],
        ['app' => 'ebeddien', 'version' => '7.1.88', 'role_id' => null, 'title' => 'eBeddien 7.1.88 – Konfirmasi overpay/ganda PSB', 'changelog' => "Pembayaran pendaftaran: konfirmasi jika sudah lunas, overpay, atau respons 409 duplikat dari API.\nBACKEND_VERSION 2.13.56.", 'released_at' => '2026-08-05 12:00:00'],
        ['app' => 'api', 'version' => '2.13.57', 'role_id' => null, 'title' => 'API 2.13.57 – Harden PII list/profil, OTP, upload', 'changelog' => "GET /user/{id}: mask NIK/KK/email/WA kecuali self/super_admin atau full_pii=1.\nget-all-pendaftar: mask telpon/email; lean fields; meta pagination opsional.\nsend-otp-ganti-wa: rate limit 3/10 menit + pesan error generik.\nUpload foto: FileUploadValidator + getimagesize + tolak polyglot PHP.", 'released_at' => '2026-08-05 12:30:00'],
