        ['app' => 'mybeddien', 'version' => '1.2.92', 'role_id' => null, 'title' => 'myBeddien 1.2.92 – Santri Boyong ditolak login', 'changelog' => "Login akses santri ditolak bila status pondok Boyong (pesan dari API).\nBACKEND_VERSION 2.13.58.", 'released_at' => '2026-08-05 12:40:00'],
