        ['app' => 'api', 'version' => '2.13.63', 'role_id' => null, 'title' => 'API 2.13.63 – Grup menu Pengaturan', 'changelog' => "Menu baru: menu.settings.payment_gateway, menu.settings.whatsapp.\nPindah Notifikasi / OTP Email / Evo / WhatsApp koneksi / WatZap ke group_label Pengaturan; nest 3 provider di bawah WhatsApp.\nsuperAdminMenus: +payment_gateway, email_otp, whatsapp.", 'released_at' => '2026-08-05 14:30:00'],
        ['app' => 'ebeddien', 'version' => '7.1.92', 'role_id' => null, 'title' => 'eBeddien 7.1.92 – Menu Pengaturan', 'changelog' => "Grup navigasi Pengaturan: Payment Gateway, Notifikasi, OTP Email, WhatsApp (submenu Evo / WhatsApp / WatZap).\nPayment Gateway keluar dari Pendaftaran → Pengaturan.\nBACKEND_VERSION 2.13.63.", 'released_at' => '2026-08-05 14:30:00'],
