        ['app' => 'daftar', 'version' => '2.2.29', 'role_id' => null, 'title' => 'Daftar 2.2.29 – Login NIK tanpa WA wajib', 'changelog' => "Login: cukup NIK; jika data sudah ada minta tanggal lahir lalu muat data dari server.\nJika NIK+TTL tidak cocok: tombol WhatsApp «Butuh bantuan untuk pendaftaran santri» (admin perbaiki manual).\nBACKEND_VERSION 2.13.66.", 'released_at' => '2026-08-07 12:30:00'],
        ['app' => 'api', 'version' => '2.13.67', 'role_id' => null, 'title' => 'API 2.13.67 – Login daftar cek nama ibu', 'changelog' => "POST /auth/login-nik: NIK yang sudah ada wajib cocok tanggal_lahir + nama ibu (santri.ibu).\nKode: ibu_required, verify_mismatch, need_help (TTL/ibu kosong di DB).", 'released_at' => '2026-08-07 12:45:00'],
        ['app' => 'daftar', 'version' => '2.2.30', 'role_id' => null, 'title' => 'Daftar 2.2.30 – Verifikasi nama ibu', 'changelog' => "Login NIK yang sudah ada: isi tanggal lahir + nama ibu.\nJika tidak cocok: WhatsApp bantuan pendaftaran (admin perbaiki manual).\nBACKEND_VERSION 2.13.67.", 'released_at' => '2026-08-07 12:45:00'],
        ['app' => 'api', 'version' => '2.13.68', 'role_id' => null, 'title' => 'API 2.13.68 – Harden login daftar', 'changelog' => "Selaras daftar 2.2.31: login-nik tetap sumber kebenaran TTL+nama ibu.\napi_version 2.13.68.", 'released_at' => '2026-08-07 12:55:00'],
        ['app' => 'daftar', 'version' => '2.2.31', 'role_id' => null, 'title' => 'Daftar 2.2.31 – Harden cek NIK login', 'changelog' => "Cek NIK gagal tidak lagi dianggap NIK baru (hindari skip verifikasi).\nRespons ttl_required/ibu_required/verify_mismatch menampilkan form TTL+nama ibu + bantuan WA.\nInterceptor: jangan treat error login-nik/daftar-wa sebagai sesi kadaluarsa.\nBACKEND_VERSION 2.13.68.", 'released_at' => '2026-08-07 12:55:00'],
