        ['app' => 'ebeddien', 'version' => '7.1.95', 'role_id' => null, 'title' => 'eBeddien 7.1.95 – Filter status pendaftar', 'changelog' => "Dashboard Pendaftaran: filter Status pendaftar (Semua / Santri Baru / Santri Lama) di samping filter lembaga.\nBACKEND_VERSION 2.13.69.", 'released_at' => '2026-08-08 15:00:00'],
        ['app' => 'api', 'version' => '2.13.70', 'role_id' => null, 'title' => 'API 2.13.70 – Tambah akses myBeddien', 'changelog' => "POST /mybeddian/v2/auth/tambah-akses-prepare (auth) + tambah-akses-consume.\nWA purpose tambah_akses: tautkan santri/pjgt/toko ke akun, balas link /profil#tambah-akses= (bukan setup-akun).", 'released_at' => '2026-08-11 19:30:00'],
