        ['app' => 'mybeddien', 'version' => '1.2.97', 'role_id' => null, 'title' => 'myBeddien 1.2.97 – Tambah akses saudara', 'changelog' => "Tambah akses: keterangan saudara, cek NIS (sudah di akun / tertaut akun lain), ajukan dengan NIK+KK, tautan Tidak tahu NIS.\nSembunyikan tab PJGT/Toko jika akun sudah punya akses tersebut.\nBACKEND_VERSION 2.13.71.", 'released_at' => '2026-08-12 03:30:00'],
