        ['app' => 'mybeddien', 'version' => '1.2.98', 'role_id' => null, 'title' => 'myBeddien 1.2.98 – Transfer saldo toko', 'changelog' => "Halaman Saldo toko: tombol Transfer aktif (seperti santri).\nKirim ke No Wallet 7 digit — tujuan bisa wallet santri atau toko lain.\nBACKEND_VERSION 2.13.73.", 'released_at' => '2026-08-12 16:00:00'],
