        ['app' => 'ebeddien', 'version' => '7.1.97', 'role_id' => null, 'title' => 'eBeddien 7.1.97 – Role & Akses disederhanakan', 'changelog' => "Pengaturan → Role & Akses: list ringkas (nama + ikon kunci/fitur + ikon user/pengurus).\nOffcanvas Kelola Akses: hanya checklist menu/aksi eBeddien (tanpa tab aplikasi/izin modul API).\nChecklist pengurus per role (sama pola halaman Fitur).\nBACKEND_VERSION 2.13.74.", 'released_at' => '2026-08-14 09:30:00'],
