        ['app' => 'api', 'version' => '2.13.76', 'role_id' => null, 'title' => 'API 2.13.76 – Bisyaroh transfer Bank Jatim', 'changelog' => "Tabel bisyaroh___transfer_batch / transfer_baris + status transfer per rekap_baris.\nEndpoint /api/bisyaroh/transfer: export-batch, upload-mutasi, batches, rilis-manual, export-retry-failed.\nRekonsiliasi mutasi Jatim: match rekening+nominal ke batch export; identitas lembaga-NIP dari batch.\nFitur: action.bisyaroh.tab.rilis, transfer.upload, transfer.reconcile.\nHistori: baris transfer berhasil ikut terlihat tanpa wajib status lembaga rilis.", 'released_at' => '2026-08-16 10:30:00'],
        ['app' => 'ebeddien', 'version' => '7.1.102', 'role_id' => null, 'title' => 'eBeddien 7.1.102 – Bisyaroh rilis Bank Jatim', 'changelog' => "Bisyaroh Review: hapus rilis set-level; Rilis per pengurus; badge status transfer; accordion ekspor multi-lembaga ditinjau (Salin angka murni + CSV batch server); upload mutasi Jatim.\nTab Rilis: arsip CSV export/mutasi, detail baris, export ulang gagal.\nCSV upload ket-2 = lembaga-nip.\nBACKEND_VERSION 2.13.76.", 'released_at' => '2026-08-16 10:30:00'],
