        ['app' => 'mybeddien', 'version' => '1.2.99', 'role_id' => null, 'title' => 'myBeddien 1.2.99 – Bulan laporan PJGT/GT', 'changelog' => "List laporan PJGT & GT hanya bulan Dzulhijjah, Safar, Rabi'ul Akhir, Jumadil Akhir, Sya'ban.\nTambah laporan dinonaktifkan di luar bulan tersebut.\nBACKEND_VERSION 2.13.77.", 'released_at' => '2026-08-17 20:40:00'],
        ['app' => 'ebeddien', 'version' => '7.1.103', 'role_id' => null, 'title' => 'eBeddien 7.1.103 – Bulan laporan UGT', 'changelog' => "Koordinator: list/filter/form hanya Dzulqa'dah, Muharram, Rabi'ul Awal, Jumadil Awal, Rajab.\nGT/PJGT: hanya Dzulhijjah, Safar, Rabi'ul Akhir, Jumadil Akhir, Sya'ban.\nBACKEND_VERSION 2.13.77.", 'released_at' => '2026-08-17 20:40:00'],
