        ['app' => 'api', 'version' => '2.13.79', 'role_id' => null, 'title' => 'API 2.13.79 – Rekonsiliasi mutasi menandai rilis', 'changelog' => "Upload/terapkan mutasi Jatim menulis status berhasil ke baris mutasi dan rekap (sebelumnya hanya ke batch export, sehingga mutasi tetap pending).\nPOST /transfer/apply-mutasi untuk file yang sudah terunggah.", 'released_at' => '2026-08-19 09:40:00'],
        ['app' => 'ebeddien', 'version' => '7.1.105', 'role_id' => null, 'title' => 'eBeddien 7.1.105 – Terapkan rekonsiliasi mutasi', 'changelog' => "Tab Rilis: file mutasi Bank Jatim bisa «Terapkan rekonsiliasi» agar 176 baris bukti bank menandai rilis (bukan tetap pending).\nBACKEND_VERSION 2.13.79.", 'released_at' => '2026-08-19 09:40:00'],
