        ['app' => 'daftar', 'version' => '2.2.33', 'role_id' => null, 'title' => 'Daftar 2.2.33 – Staging alutsmani.my.id', 'changelog' => "Staging: https://daftar.alutsmani.my.id → API https://api.alutsmani.my.id.\nBACKEND_VERSION 2.13.80.", 'released_at' => '2026-08-20 07:00:00'],
        ['app' => 'api', 'version' => '2.13.81', 'role_id' => null, 'title' => 'API 2.13.81 – Status santri wajib terisi', 'changelog' => "SantriStatusHelper::ensureCurrentStatus: setiap santri wajib punya status aktif.\napplyCurrentStatus tidak boleh mengosongkan status.\nCreate santri/pendaftaran & boyong selalu mengisi santri___status + santri.id_status.\nProduction: 570 status kosong dipulihkan (Boyong/Khoriji).", 'released_at' => '2026-08-20 15:50:00'],
        ['app' => 'api', 'version' => '2.13.82', 'role_id' => null, 'title' => 'API 2.13.82 – Status santri enum di kode', 'changelog' => "Status santri tetap 6 nilai (Mukim, Boyong, Khoriji, Guru Tugas, Pengurus, Alumni) divalidasi di kode — tanpa tabel master `status`.\nKolom string santri.status_santri + santri___status.status_santri; drop id_status.\nUWABA harga dasar flat per status; jenjang Khoriji ikut formal.\nMigrasi: 20260820160000_simplify_santri_status_enum.", 'released_at' => '2026-08-20 16:15:00'],
        ['app' => 'ebeddien', 'version' => '7.1.107', 'role_id' => null, 'title' => 'eBeddien 7.1.107 – Status santri & UWABA sederhana', 'changelog' => "Halaman Status Santri read-only (6 enum).\nDropdown status + Alumni; bulk/UWABA tidak wajib kategori untuk hitung harga.\nuwaba-prices.json: harga dasar flat per status.\nBACKEND_VERSION 2.13.82.", 'released_at' => '2026-08-20 16:15:00'],
        ['app' => 'api', 'version' => '2.13.83', 'role_id' => null, 'title' => 'API 2.13.83 – Status santri wajib terisi', 'changelog' => "Backfill status kosong + kolom santri.status_santri NOT NULL.\nAPI tolak status kosong/invalid; list pakai COALESCE(histori, kolom santri).\nMigrasi: 20260820170000_enforce_santri_status_not_empty.", 'released_at' => '2026-08-20 16:40:00'],
        ['app' => 'ebeddien', 'version' => '7.1.108', 'role_id' => null, 'title' => 'eBeddien 7.1.108 – Status santri wajib di UI', 'changelog' => "Form Edit Santri, Pendaftaran, Biodata: status santri wajib dipilih sebelum simpan.\nBACKEND_VERSION 2.13.83.", 'released_at' => '2026-08-20 16:40:00'],
        ['app' => 'api', 'version' => '2.13.84', 'role_id' => null, 'title' => 'API 2.13.84 – Audit status santri', 'changelog' => "Dashboard GROUP BY status dengan fallback kolom.\nIjin status COALESCE histori+kolom.\nPrint UWABA pakai UwabaPricingHelper::loadPricesJson.", 'released_at' => '2026-08-20 17:00:00'],
        ['app' => 'ebeddien', 'version' => '7.1.109', 'role_id' => null, 'title' => 'eBeddien 7.1.109 – Audit UWABA tanpa wajib kategori', 'changelog' => "Lengkapi/Generate UWABA tidak wajib kategori.\nDropdown status pakai enum lengkap; Biodata tidak clear kategori saat ganti status.\nBACKEND_VERSION 2.13.84.", 'released_at' => '2026-08-20 17:00:00'],
