        ['app' => 'api', 'version' => '2.13.85', 'role_id' => null, 'title' => 'API 2.13.85 – Chat UWABA kategori Banin/Banat', 'changelog' => "AiUwabaBiayaChatContext: kategori dari pesan hanya Banin/Banat (bukan PAUD/SD nested harga).", 'released_at' => '2026-08-20 17:05:00'],
        ['app' => 'ebeddien', 'version' => '7.1.110', 'role_id' => null, 'title' => 'eBeddien 7.1.110 – Update santri di Data Ijin', 'changelog' => "DetailSantriOffcanvas Ijin: kategori Banin/Banat tidak di-clear saat ganti status; daerah/kamar hanya Mukim.\nBulk edit status pakai enum lengkap.", 'released_at' => '2026-08-20 17:15:00'],
        ['app' => 'ebeddien', 'version' => '7.1.111', 'role_id' => null, 'title' => 'eBeddien 7.1.111 – Produksi status santri', 'changelog' => "EditSantri: keluar Mukim membersihkan daerah/kamar (kategori tetap).\nRilis produksi selaras API 2.13.85 / daftar 2.2.34.", 'released_at' => '2026-08-20 17:30:00'],
        ['app' => 'api', 'version' => '2.13.86', 'role_id' => null, 'title' => 'API 2.13.86 – Tutup ijin/shohifah publik + harden sesi', 'changelog' => "GET /public/ijin & /public/shohifah: wajib auth (bukan anonim).\nGET/POST /mybeddian/v2/shohifah: login santri; tulis hanya Sya'ban–Ramadhan–Syawal (kalender pesantren).\nAuthMiddleware: cek session JWT santri fail-closed.\nCORS LAN hanya APP_ENV local; HttpsMiddleware X-Forwarded-Proto; rate limit /public/wa/check; pagination uwaba/all-data.", 'released_at' => '2026-08-20 19:45:00'],
        ['app' => 'ebeddien', 'version' => '7.1.112', 'role_id' => null, 'title' => 'eBeddien 7.1.112 – Redirect ijin/shohifah ke myBeddien', 'changelog' => "/public/ijin & /public/shohifah redirect ke myBeddien (login).\nQR cetak shohifah mengarah ke myBeddien /santri/shohifah.\nHapus item Ijin/Shohifah dari BottomNav portal publik.\nToken setup/ubah password pakai #token= (bukan ?token=).\nBACKEND_VERSION 2.13.86.", 'released_at' => '2026-08-20 19:45:00'],
